module pokenom_painter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] M,\n    input wire [3:0] N,\n    input wire [3:0] c_0,\n    input wire [3:0] c_1,\n    input wire [3:0] c_2,\n    input wire [3:0] c_3,\n    input wire [3:0] c_4,\n    input wire [3:0] c_5,\n    input wire [3:0] c_6,\n    input wire [3:0] c_7,\n    output reg done,\n    output reg [31:0] X,\n    output reg [31:0] Y_m\n);\n\n    parameter MOD = 32'd100003;\n\n    reg [4:0] state;\n    reg [31:0] fact;\n    reg [3:0] i, j;\n    reg [7:0] S;\n    reg [7:0] T;\n    reg [7:0] T_minus_2;\n    reg [31:0] H_blue;\n    reg [31:0] H_red;\n    reg [31:0] numerator;\n    reg [31:0] denominator;\n    reg [31:0] inv_denom;\n    reg [31:0] a, b, x0, x1;\n    reg [3:0] c_reg [0:7];\n    reg [3:0] B_cols, R_cols;\n    reg [3:0] red_col_heights [0:7];\n\n    localparam [4:0] IDLE              = 5'd0;\n    localparam [4:0] READ_C            = 5'd1;\n    localparam [4:0] COMPUTE_T         = 5'd2;\n    localparam [4:0] COMPUTE_FACT      = 5'd3;\n    localparam [4:0] SETUP_BLUE        = 5'd4;\n    localparam [4:0] COMPUTE_BLUE      = 5'd5;\n    localparam [4:0] SETUP_RED         = 5'd6;\n    localparam [4:0] COMPUTE_RED       = 5'd7;\n    localparam [4:0] CALC_NUMERATOR    = 5'd8;\n    localparam [4:0] CALC_DENOMINATOR  = 5'd9;\n    localparam [4:0] CALC_INV          = 5'd10;\n    localparam [4:0] CALC_RESULT       = 5'd11;\n    localparam [4:0] FINISH            = 5'd12;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            X <= 32'd0;\n            Y_m <= 32'd0;\n            S <= 8'd0;\n            T <= 8'd0;\n            T_minus_2 <= 8'd0;\n            fact <= 32'd1;\n            H_blue <= 32'd1;\n            H_red <= 32'd1;\n            numerator <= 32'd0;\n            denominator <= 32'd0;\n            inv_denom <= 32'd0;\n            B_cols <= 4'd0;\n            R_cols <= 4'd0;\n            for (integer idx = 0; idx < 8; idx = idx + 1) begin\n                c_reg[idx] <= 4'd0;\n                red_col_heights[idx] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= READ_C;\n                        i <= 4'd0;\n                        S <= 8'd0;\n                    end\n                end\n\n                READ_C: begin\n                    case (i)\n                        3'd0: c_reg[0] <= c_0;\n                        3'd1: c_reg[1] <= c_1;\n                        3'd2: c_reg[2] <= c_2;\n                        3'd3: c_reg[3] <= c_3;\n                        3'd4: c_reg[4] <= c_4;\n                        3'd5: c_reg[5] <= c_5;\n                        3'd6: c_reg[6] <= c_6;\n                        3'd7: c_reg[7] <= c_7;\n                    endcase\n                    if (i < N - 1) begin\n                        i <= i + 1;\n                    end else begin\n                        state <= COMPUTE_T;\n                        i <= 4'd0;\n                        S <= S + c_reg[i];  // Final sum\n                    end\n                end\n\n                COMPUTE_T: begin\n                    T <= M * N;\n                    T_minus_2 <= (M * N) - 2;\n                    state <= COMPUTE_FACT;\n                    i <= 4'd1;\n                    fact <= 32'd1;\n                end\n\n                COMPUTE_FACT: begin\n                    if (i <= T_minus_2) begin\n                        fact <= (fact * i) % MOD;\n                        i <= i + 1;\n                    end else begin\n                        state <= SETUP_BLUE;\n                    end\n                end\n\n                SETUP_BLUE: begin\n                    B_cols <= 4'd0;\n                    for (integer idx = 0; idx < N; idx = idx + 1) begin\n                        if (c_reg[idx] > 0) B_cols <= idx + 1;\n                    end\n                    state <= COMPUTE_BLUE;\n                    i <= 4'd0;\n                    j <= 4'd0;\n                    H_blue <= 32'd1;\n                end\n\n                COMPUTE_BLUE: begin\n                    if (i < B_cols) begin\n                        if (j < c_reg[i]) begin\n                            integer count_right;\n                            count_right = 4'd0;\n                            for (integer col = i + 1; col < B_cols; col = col + 1) begin\n                                if (c_reg[col] > j) count_right = count_right + 1;\n                            end\n                            H_blue <= (H_blue * (j + count_right + 1)) % MOD;\n                            j <= j + 1;\n                        end else begin\n                            j <= 4'd0;\n                            i <= i + 1;\n                        end\n                    end else begin\n                        state <= SETUP_RED;\n                    end\n                end\n\n                SETUP_RED: begin\n                    R_cols <= 4'd0;\n                    for (integer idx = 0; idx < N; idx = idx + 1) begin\n                        red_col_heights[idx] <= M - c_reg[N-1-idx];\n                        if (red_col_heights[idx] > 0) R_cols <= idx + 1;\n                    end\n                    state <= COMPUTE_RED;\n                    i <= 4'd0;\n                    j <= 4'd0;\n                    H_red <= 32'd1;\n                end\n\n                COMPUTE_RED: begin\n                    if (i < R_cols) begin\n                        if (j < red_col_heights[i]) begin\n                            integer count_right;\n                            count_right = 4'd0;\n                            for (integer col = i + 1; col < R_cols; col = col + 1) begin\n                                if (red_col_heights[col] > j) count_right = count_right + 1;\n                            end\n                            H_red <= (H_red * (j + count_right + 1)) % MOD;\n                            j <= j + 1;\n                        end else begin\n                            j <= 4'd0;\n                            i <= i + 1;\n                        end\n                    end else begin\n                        state <= CALC_NUMERATOR;\n                    end\n                end\n\n                CALC_NUMERATOR: begin\n                    numerator <= (((fact * S) % MOD) * (T - S)) % MOD;\n                    state <= CALC_DENOMINATOR;\n                end\n\n                CALC_DENOMINATOR: begin\n                    denominator <= (H_blue * H_red) % MOD;\n                    state <= CALC_INV;\n                    a <= denominator;\n                    b <= MOD;\n                    x0 <= 32'd1;\n                    x1 <= 32'd0;\n                end\n\n                CALC_INV: begin\n                    if (b != 0) begin\n                        integer quotient = a / b;\n                        integer remainder = a % b;\n                        integer new_x1;\n                        new_x1 = x0 - quotient * x1;\n                        a <= b;\n                        b <= remainder;\n                        x0 <= x1;\n                        x1 <= new_x1;\n                    end else begin\n                        inv_denom <= (x0 < 0) ? x0 + MOD : x0;\n                        state <= CALC_RESULT;\n                    end\n                end\n\n                CALC_RESULT: begin\n                    Y_m <= (numerator * inv_denom) % MOD;\n                    X <= 32'd0;\n                    state <= FINISH;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule